// Heliotrope sound engine: all sounds are generated by code (no mp3 needed).
const LOUD = 1.15
const MUSIC = 0.45

let ctx, master, reverbInput, musicGain

function ac() {
  if (!ctx) {
    const C = window.AudioContext || window.webkitAudioContext
    if (!C) return null
    ctx = new C()
    master = ctx.createGain()
    master.gain.value = 0
    master.gain.setTargetAtTime(LOUD, ctx.currentTime, 0.08)
    const comp = ctx.createDynamicsCompressor()
    comp.threshold.value = -20
    comp.knee.value = 24
    comp.ratio.value = 3
    comp.attack.value = 0.015
    comp.release.value = 0.22
    master.connect(comp)
    comp.connect(ctx.destination)
  }
  if (ctx.state === 'suspended') ctx.resume()
  return ctx
}

function getReverbInput(c) {
  if (!reverbInput) {
    const length = Math.floor(c.sampleRate * 1.1)
    const buffer = c.createBuffer(2, length, c.sampleRate)
    for (let channel = 0; channel < 2; channel += 1) {
      const samples = buffer.getChannelData(channel)
      for (let i = 0; i < length; i += 1) {
        samples[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / length, 2.8)
      }
    }
    const convolver = c.createConvolver()
    convolver.buffer = buffer
    const wet = c.createGain()
    wet.gain.value = 0.16
    convolver.connect(wet)
    wet.connect(master)
    reverbInput = convolver
  }
  return reverbInput
}

const N = (m) => 440 * Math.pow(2, (m - 69) / 12) // midi -> Hz

// soft bell note. midi = note number; `to` = optional end frequency in Hz
function note(midi, { at = 0, len = 0.5, vol = 0.12, type = 'sine', to = null, out = null, verb = 1 } = {}) {
  const c = ac()
  if (!c) return
  const t = c.currentTime + at
  const f = N(midi)
  const osc = c.createOscillator()
  const g = c.createGain()
  osc.type = type
  osc.frequency.setValueAtTime(f, t)
  if (to) osc.frequency.exponentialRampToValueAtTime(to, t + len)
  const attack = Math.min(0.025, len * 0.2)
  const release = Math.min(0.14, len * 0.35)
  g.gain.setValueAtTime(0.0001, t)
  g.gain.linearRampToValueAtTime(vol, t + attack)
  g.gain.setValueAtTime(vol, t + len - release)
  g.gain.exponentialRampToValueAtTime(0.0001, t + len)
  osc.connect(g)
  g.connect(out || master)
  if (verb) {
    const s = c.createGain()
    s.gain.value = verb
    g.connect(s)
    s.connect(getReverbInput(c))
  }
  osc.start(t)
  osc.stop(t + len + 0.05)
  if (type === 'sine' && !out) {
    const o2 = c.createOscillator()
    const g2 = c.createGain()
    o2.frequency.value = f * 2
    g2.gain.setValueAtTime(0.0001, t)
    g2.gain.linearRampToValueAtTime(vol * 0.18, t + Math.min(0.02, len * 0.2))
    g2.gain.exponentialRampToValueAtTime(0.0001, t + len * 0.6)
    o2.connect(g2)
    g2.connect(master)
    o2.start(t)
    o2.stop(t + len)
  }
}

function hiss({ at = 0, len = 0.4, vol = 0.05, freq = 1500, q = 0.7 } = {}) {
  const c = ac()
  if (!c) return
  const t = c.currentTime + at
  const buf = c.createBuffer(1, Math.floor(c.sampleRate * len), c.sampleRate)
  const d = buf.getChannelData(0)
  for (let i = 0; i < d.length; i += 1) d[i] = Math.random() * 2 - 1
  const s = c.createBufferSource()
  s.buffer = buf
  const f = c.createBiquadFilter()
  f.type = 'bandpass'
  f.frequency.value = freq
  f.Q.value = q
  const g = c.createGain()
  const attack = Math.min(0.06, len * 0.25)
  const release = Math.min(0.16, len * 0.3)
  g.gain.setValueAtTime(0.0001, t)
  g.gain.linearRampToValueAtTime(vol, t + attack)
  g.gain.setValueAtTime(vol, t + len - release)
  g.gain.exponentialRampToValueAtTime(0.0001, t + len)
  s.connect(f)
  f.connect(g)
  g.connect(master)
  s.start(t)
}

// pentatonic: C D E G A C
const P = [72, 74, 76, 79, 81, 84]

const SOUNDS = {
  tap: () => note(88, { len: 0.07, vol: 0.06, verb: 0 }),
  pop: () => note(72, { len: 0.12, vol: 0.12, to: N(96) }),
  bubble: () => note(76, { len: 0.1, vol: 0.09, to: N(100) }),
  meow: () => {
    note(72, { len: 0.32, type: 'triangle', vol: 0.09, to: N(80) })
    note(80, { at: 0.28, len: 0.34, type: 'triangle', vol: 0.08, to: N(70) })
  },
  purr: () => {
    for (let i = 0; i < 10; i += 1) note(40, { at: i * 0.08, len: 0.1, type: 'triangle', vol: 0.05, verb: 0 })
  },
  munch: () => {
    for (let i = 0; i < 3; i += 1) hiss({ at: i * 0.17, len: 0.1, vol: 0.08, freq: 900, q: 1.2 })
  },
  flush: () => hiss({ len: 1.6, vol: 0.07, freq: 1000, q: 0.5 }),
  water: () => hiss({ len: 0.8, vol: 0.04, freq: 3000, q: 0.4 }),
  sleep: () => [P[3], P[2], P[0]].forEach((m, i) => note(m - 12, { at: i * 0.28, len: 0.9, vol: 0.09 })),
  wake: () => [P[0], P[2], P[3]].forEach((m, i) => note(m - 12, { at: i * 0.16, len: 0.6, vol: 0.09 })),
  bounce: () => note(55, { len: 0.12, vol: 0.12, to: N(40), type: 'triangle', verb: 0 }),
  success: () => [P[0], P[2], P[3], P[5]].forEach((m, i) => note(m, { at: i * 0.09, len: 0.7, vol: 0.09 })),
  levelup: () => P.forEach((m, i) => note(m, { at: i * 0.1, len: 0.9, vol: 0.09 })),
  error: () => {
    note(60, { len: 0.25, type: 'triangle', vol: 0.09 })
    note(56, { at: 0.14, len: 0.35, type: 'triangle', vol: 0.09 })
  },
  open: () => [67, 71, 74, 79, 83].forEach((m, i) => note(m, { at: i * 0.1, len: 0.75, vol: 0.07, verb: 0 })),
}

export function play(name) {
  try { SOUNDS[name]?.() } catch (e) { console.error('Sound failed:', e) }
}

export function playOpening() {
  const go = () => {
    play('open')
    removeEventListener('pointerdown', go)
    removeEventListener('keydown', go)
  }
  addEventListener('pointerdown', go)
  addEventListener('keydown', go)
}

export function installGlobalSounds() {
  document.addEventListener(
    'pointerdown',
    (e) => {
      const el = e.target.closest?.('button, a, [role="button"], [role="switch"], summary')
      if (el && !el.disabled) play('tap')
    },
    true,
  )
}

/* ---------- calm background music (generated, loops forever) ---------- */
const CHORDS = [
  [60, 64, 67, 71],
  [57, 60, 64, 67],
  [53, 57, 60, 64],
  [55, 59, 62, 64],
]
const BAR = 4
let musicTimer = null
let musicOn = false
let bar = 0

function pad(midi, len) {
  const c = ac()
  const t = c.currentTime
  const osc = c.createOscillator()
  const g = c.createGain()
  osc.type = 'sine'
  osc.frequency.value = N(midi)
  g.gain.setValueAtTime(0.0001, t)
  g.gain.linearRampToValueAtTime(0.05, t + 1.2)
  g.gain.linearRampToValueAtTime(0.0001, t + len)
  osc.connect(g)
  g.connect(musicGain)
  osc.start(t)
  osc.stop(t + len + 0.1)
}

function scheduleBar() {
  const c = ac()
  if (!c || !musicOn) return
  const chord = CHORDS[bar % CHORDS.length]
  chord.forEach((m) => pad(m - 12, BAR + 1.5))
  for (let i = 0; i < 3; i += 1) {
    const m = chord[Math.floor(Math.random() * chord.length)] + 12
    note(m, { at: 0.6 + i * 1.2 + Math.random() * 0.3, len: 1.8, vol: 0.05, out: musicGain, verb: 1.2 })
  }
  bar += 1
}

export function startMusic() {
  const c = ac()
  if (!c || musicOn) return
  if (!musicGain) {
    musicGain = c.createGain()
    musicGain.gain.value = MUSIC
    musicGain.connect(master)
    musicGain.connect(getReverbInput(c))
  }
  musicOn = true
  scheduleBar()
  musicTimer = setInterval(scheduleBar, BAR * 1000)
}

export function stopMusic() {
  musicOn = false
  clearInterval(musicTimer)
  musicTimer = null
}

export function installMusic() {
  const go = () => {
    startMusic()
    removeEventListener('pointerdown', go)
    removeEventListener('keydown', go)
  }
  addEventListener('pointerdown', go)
  addEventListener('keydown', go)
  document.addEventListener('visibilitychange', () => {
    if (document.hidden) stopMusic()
    else if (ctx) startMusic()
  })
}